#!/usr/bin/env python3
"""Render final full-SQL and real-AM results from verified unpooled analyses."""
import json,pathlib
r=pathlib.Path(__file__).resolve().parent
A={};P={}
for mode in ['screen','full']:
 for c in [0,1]:
  d=r/f'results-r3/{mode}-cohort{c}'
  assert json.loads((d/'status.json').read_text())['status']=='PASS'
  A[mode,c]=json.loads((d/'absolute.json').read_text());P[mode,c]=json.loads((d/'pairs.json').read_text())
def absolute(mode,c,case,role,metric):return next(x for x in A[mode,c] if (x['case'],x['role'],x['metric'])==(case,role,metric))
def pair(mode,c,case,left,right,metric):return next(x for x in P[mode,c] if (x['case'],x['left'],x['right'],x['metric'])==(case,left,right,metric))
def av(mode,case,role,metric='sql_execution_ms'):
 return ' / '.join(f"{absolute(mode,c,case,role,metric)['median']:.4f}" for c in [0,1])
def pv(mode,case,left='B',right='C9',metric='backend_cpu_ms'):
 return ' / '.join(f"{pair(mode,c,case,left,right,metric)['percent']['median']:+.2f}" for c in [0,1])
fullcases=list(dict.fromkeys(x['case'] for x in A['full',0]))
repeat=[case for case in fullcases if all(pair('full',c,case,'B','C9','backend_cpu_ms')['percent']['median']>0 for c in [0,1])]
targets={case:{str(c):pair('full',c,case,'B','C9','backend_cpu_ms')['percent']['median'] for c in [0,1]} for case in ['inline','absent']}
checks=json.loads((r/'evidence-r3/FINAL-CHECKS-final-r1.json').read_text())
assert checks['status']=='PASS'
strict_targets=all(v<0 for d in targets.values() for v in d.values())
lead=('C9 improves both inline and absent CPU in both full-SQL cohorts.' if strict_targets else 'C9 fixes the absent cost and improves the measured native inline loop; full SQL inline/control movements must be read from the unpooled table below.')
lines=['# GIN regression repair: full SQL and real-AM results','', lead+' It combines direct logical-TID ordering and adaptive decoded advancement with lazy posting consumption, including deferred first-page decoding with an exact frequency count. This is a tested prototype on fixed B72, not a current-master or general speedup claim.','', 'Selected source: 0ab3bd65c8957ea5e25f9ef8981401f0616d99de, branch experiments/gin-combined-v9-b72-20261110. Baseline B72 is 72b9498df9a369e747f8d96efb5a6cd33c2451e2 plus the same supplied prerequisite in every tree (fixed base 8a8c475037bfde101da23cc9b0364c9c020eca93). Earlier published observations are historical context, not pooled data.','', '## Full SQL confirmation','', 'Absolute columns are retained EXPLAIN executor medians in ms, cohort0 / cohort1. Paired columns are same-round whole-command backend CPU percent medians. Negative means less time. They are different measurement boundaries, not ratios of the displayed absolute medians. Every full-SQL query uses the original data/probe counts.','', '| Case | B executor ms | L4 executor ms | C9 executor ms | L4/B CPU % | C9/B CPU % | C9/L4 CPU % |','|---|---:|---:|---:|---:|---:|---:|']
for case in fullcases:
 lines.append('| '+' | '.join([case]+[av('full',case,role) for role in ['B','L4','C9']]+[pv('full',case,l,rr) for l,rr in [('B','L4'),('B','C9'),('L4','C9')]])+' |')
lines+=['','## Real-AM diagnostic screen','', 'These are newly executed real index_rescan/index_getbitmap/tbm_free loops on the actual backend, separate from SQL/heap visibility. Absolute columns and paired percentages in this table both measure the internal loop process CPU. No modeled loader or private extracted body is used.','', '| Case | B AM CPU ms | L4 AM CPU ms | C9 AM CPU ms | C9/B CPU % | C9/L4 CPU % |','|---|---:|---:|---:|---:|---:|']
for case in ['am_inline','am_absent','am_skew1000','am_full']:
 lines.append('| '+' | '.join([case]+[av('screen',case,role,'am_loop_cpu_ms') for role in ['B','L4','C9']]+[pv('screen',case,l,rr,'am_loop_cpu_ms') for l,rr in [('B','C9'),('L4','C9')]])+' |')
lines+=['','## Spread, negatives, and limits','', 'Full-SQL cases with positive C9/B CPU paired medians in both cohorts: '+(', '.join(repeat) if repeat else 'none')+'. All cases and all pairs remain in the table and raw evidence; this sign check alone is not a significance test. Check B/T and C9/T alongside B, without normalizing by either.','', '| Full SQL control | C9/B CPU % | T/B CPU % | C9/T CPU % |','|---|---:|---:|---:|']
for case in ['inline','absent','or_forced','single_forced','inline_single','dense_and','array_dense','lossy_and','seq_control']:
 lines.append('| '+' | '.join([case,pv('full',case),pv('full',case,'B','T'),pv('full',case,'T','C9')])+' |')
lines+=['','The R3 screen had C9 OR +5.95/-2.79% and Seq +9.06/-5.96% across reversed cohorts; those first-cohort increases did not repeat there. Earlier repeated off-path Seq costs are preserved as unresolved historical observations. The same-binary calibration in R2 also moved, but does not prove a harmless cause or rule out source/layout effects. No cache/branch explanation is inferred from software samples or identical instruction shapes.','', 'V7 reduced scan-entry state from 848 to 832 bytes but did not repair inline; R2 native inline remained about +10% versus baseline. L8/L9 alone left native inline +5.97/+7.09% and +4.58/+5.11%, respectively; L9 also had OR +3.75/+6.90%. All failed/partial improvements and their source branches are retained. See R2-RESULTS.md and R3-SCREEN-RESULTS.md.','', 'Absolute executor min/median/max for the repaired targets and key controls:','', '| Cohort | Case | B min / median / max ms | C9 min / median / max ms |','|---:|---|---:|---:|']
for c in [0,1]:
 for case in ['inline','absent','skew1000','jsonb','or_forced','seq_control']:
  vals=[]
  for role in ['B','C9']:
   x=absolute('full',c,case,role,'sql_execution_ms');vals.append(' / '.join(f'{x[k]:.6f}' for k in ['min','median','max']))
  lines.append('| '+' | '.join([str(c),case]+vals)+' |')
lines+=['','Every absolute min/median/max, SD/MAD, all metric boundaries, every direct pair and per-round observation is preserved in results-r2/, results-r3/ and evidence-r2/, evidence-r3/. No sample trimming, cohort pooling or twin correction. The former holdout filenames are historical; these are no longer unseen discovery cases.','', '## Executed validation and scope','', '- VM158: 8 logical CPUs/4 physical cores, 16GB RAM, shared host. No foreign job or configuration was changed. The archive host was not used. CPU 0/4 server/client then 4/0, reversed roles/physical slots/session births/case order. Identical B/T ELFs, unchanged fixtures and frozen queries.','- GCC 13.3.0, -O2 -g -fno-lto, OpenSSL, no ICU/readline, nice 10, make -j2, common source/build/compiled-prefix paths with separate DESTDIR installs. R2 five clean builds; R3 clean B/C9_assert and incremental L4/L8/L9/C9, all source/header manifests verified. Every L8/L9/C9 release transition changed exactly ginget.o among backend objects. All eleven builds passed original 239 core tests each, without expected regeneration.','- Every R3 campaign first qualified all six variants on 25 ordered Seq/GIN multisets, scalar answers/expected plans, eight prepared-query comparisons with cached rescans, and four AM answers. C9_assert independently decoded first-page counts to verify exact cardinality. All 25 multisets repeat per measured role/cohort. Core has only a weak existing fuzzy-search smoke test; no new statistical fuzzy-sampling or legacy-page migration validation is claimed.','- Completed R2 null: 660 raw/600 retained/60 warm; R2 screen 3080/2800/280. Completed R3 screen: 2688/2304/384; full SQL: 2800/2400/400. All warm and failed-attempt records stay separate. The R1 adapter error produced zero timing samples and is documented in NOT-AM-ADAPTER-r1.md.','- Two warm+12 retained balanced rounds per R3 case. Each measured call follows an extra literal-answer execution. JIT/parallel/memoize/autovacuum off; shared_buffers 512MB, work_mem 64MB except the unchanged 64kB lossy case, explicit system timing clock. Recorded retained root-plan IO/WAL and whole-command read/write byte counters are reported in each analysis receipt.','- Independent local raw reconstruction verifies order/roles/answers/counts/hashes and matches remote analyses; only relative 3e-15 rounding in sample SD across Python versions is tolerated. All 68 ordinary campaign cluster directories across both waves were checked shut down, measured postmaster/backend PIDs and sockets absent, installs/final sources/seeds/runtime/AM modules unchanged. At the completed-wave final snapshots no process used the owned install/build executables; a later separate diagnostic is outside those snapshots.','- Real exported C9 .diff was independently applied to the exact fixed-base files and matched the executed three-file snapshot. Code branches, including negatives, were pushed and ls-remote verified. Publication receipts outside the frozen packet record results-branch and S3 verification.','', 'No current upstream master, CREATE INDEX throughput, independent-host confidence, exhaustive prior-art search, or universal speedup claim. These are known algorithmic ingredients; concrete contribution and previous discussion are in PRIOR-ART.md. Run instructions, exact dependencies/source/build flags/data creation/commands/metric boundaries are in REPRODUCE.md. The English mailing-list draft remains UNSENT.']
(r/'RESULTS.md').write_text('\n'.join(lines)+'\n')
sel=dict(status=('TARGET_CPU_IMPROVEMENTS_IN_BOTH_FULL_SQL_COHORTS' if strict_targets else 'ABSENT_AND_NATIVE_INLINE_REPAIRED_FULL_SQL_INLINE_MIXED'),selected='C9',commit='0ab3bd65c8957ea5e25f9ef8981401f0616d99de',targets_backend_cpu_percent=targets,cases_with_positive_paired_CPU_medians_both_cohorts=repeat,limits='Single shared VM and fixed B72; retain all control costs/spreads. No current-master/general speedup claim.')
(r/'results-r3/FULL-DECISION.json').write_text(json.dumps(sel,indent=2)+'\n')
draft=['To: pgsql-hackers@lists.postgresql.org','Subject: [PATCH] Reduce GIN posting-list advancement and startup decoding costs','Status: UNSENT DRAFT','', 'Hi,','', 'Attached is a prototype combining adaptive advancement in decoded GIN TID lists with deferred consumption of private compressed posting-page snapshots. It follows up on the separate advance V4 / lazy V4 experiments. The aim here is to retain their selective-query gains while removing the observed tiny-inline and absent-query costs.','', 'There are three parts: compare logical unsigned TID keys directly when only ordering is needed; use two cheap probes before exponential/binary upper-bound advancement; and defer compressed first-page materialization for multi-entry scans. For the last part, counting varbyte terminators with masked popcount gives the exact original first-page cardinality, preserving the frequency estimate and entry ordering/sampling thresholds. Singleton, uncompressed and empty startup paths remain eager. Existing ownership and buffer-pin rules are retained; no new on-disk format is introduced.','', 'New full-backend SQL results on fixed B72 plus the same common prerequisite in every tree are below. Numbers are cohort 0 / cohort 1; the two CPU/slot/session/case-order cohorts are kept separate. Absolute columns are executor medians in ms, while CPU percentages are medians of direct same-round whole-command backend CPU ratios.','', 'case | B executor ms | combined executor ms | combined/B CPU %']
for case in ['skew1000','skew127','jsonb','intarray','builtin_array','skew_group4096','phrase_positive','inline','absent','or_forced','single_forced','dense_and','array_dense','lossy_and','seq_control']:
 draft.append(' | '.join([case,av('full',case,'B'),av('full',case,'C9'),pv('full',case)]))
draft+=['', 'A separate real-AM C adapter loops over the actual index_rescan/index_getbitmap/tbm_free path, compiled against the installed server public headers. Its internal process-CPU medians show combined/B '+pv('screen','am_inline',metric='am_loop_cpu_ms')+'% for tiny inline and '+pv('screen','am_absent',metric='am_loop_cpu_ms')+'% for absent. These are not heap-visibility or SQL-throughput measurements. The native and SQL boundaries are reported separately.','', 'Full SQL still has positive OR and single-rare CPU medians versus B in both cohorts. The second cohort is near/under the exact twin, but this is not normalized away and the prototype is not ready to merge without resolving or bounding those costs. A separate real-AM OR/rare diagnostic follows this frozen packet.','', 'Negative experiments are included: shrinking private scan-entry state (V7) did not repair inline. Boolean ordering alone (L8), and first-page deferral without adaptive advancement (L9), still had native inline costs; L9 also had repeated OR costs. The combined candidate is measured directly, not inferred by adding gains from alternatives. The screen had OR/Seq increases in one cohort that reversed in the other. All full-SQL controls, baseline twins, ranges and per-round values are retained; no samples are trimmed, pooled or normalized by the twin. Earlier off-path Seq movements remain historical unresolved observations, not proof of an algorithmic cause or harmless noise.','', 'Setup: VM158, GCC 13.3, -O2 -g -fno-lto, OpenSSL, no ICU/readline, release timing builds, JIT/parallel/memoize/autovacuum off, 512MB shared_buffers and warm-cache synthetic data (200000 generated docs plus NULL/empty rows and a small inline fixture). Full SQL uses 25 unchanged queries, two warm and 12 retained balanced rounds per role in each cohort. Exact data/index definitions, build flags/revisions, dependencies and commands for repeating both the real-AM and SQL tests are in REPRODUCE.md; the packet includes raw observations, absolute ranges, SD/MAD and every pair. No CREATE INDEX or current-master result is claimed.','', 'All builds passed the original 239 tests, including an assertion build. Ordinary ordered Seq/GIN multisets, prepared rescans, expected paths and AM answers matched. Assertions independently check first-page cardinality by decoding. The executed source, object/header identities and clean owned-cluster shutdowns are recorded. The bundled diff was reapplied to the exact fixed baseline and matched the measured source.','', 'Previous discussion: the earlier fast-scan work [1,2] already introduced advancePast and compressed segment skipping. Galloping search, boolean ordering and lazy consumption are established techniques. The contribution is their GIN integration, exact first-page counting and measured tradeoffs, not a priority claim. The extraction/sort/build-accumulator work [3,4] concerns an earlier phase; its gains are not mixed with these consumer measurements. The bounded prior-art review and negative results are included.','', 'Candidate: patches/gin-lazy-adaptive-v9-over-fixed-b72.diff (after fixed base 8a8c475037bfde101da23cc9b0364c9c020eca93). Incremental format-patches and complete B72 source plans are also included; these are alternative forms, not patches to apply twice.','', 'Code: https://github.com/pg-sharding/cpg/tree/experiments/gin-combined-v9-b72-20261110','Results/reproduction: https://github.com/pg-sharding/cpg/tree/experiments/gin-regression-repair-results-b72-20261110/review/gin-regression-repair-20261110','', '[1] https://www.postgresql.org/message-id/52E42AD0.5060600%40vmware.com','[2] https://www.postgresql.org/message-id/52F36245.6070006%40vmware.com','[3] https://www.postgresql.org/message-id/5d366878-2007-4d31-861e-19294b7a583b%40gmail.com','[4] https://www.postgresql.org/message-id/10afd923-38f4-451c-af89-34f8654533cb%40googlemail.com','']
(r/'email-draft-UNSENT.txt').write_text('\n'.join(draft))
print(json.dumps(sel))
